lessons.guideMain:
extends Node2D
var score := 0
var target := 5
enum State { PLAYING, WON, LOST }
var state: State = State.PLAYING

func _ready() -> void:
    for child in get_children():
        if child.has_signal("collected"):
            child.collected.connect(add_score)
    $Hazard.hit.connect(lose)
    update_score()

func add_score() -> void:
    if state != State.PLAYING:
        return
    score += 1
    update_score()

func update_score() -> void:
    $CanvasLayer/Score.text = "Score: %s / %s" % [score, target]

func finish(next_state: State, message: String) -> void:
    if state != State.PLAYING:
        return
    state = next_state
    $Player.enabled = false
    $CanvasLayer/Message.text = message

func lose() -> void:
    finish(State.LOST, "Try another route! Replay to restart.")

